content.content:
#cloud-config
package_update: true
packages:
  - docker.io
  - docker-compose-v2

write_files:
  - path: /opt/kip/.env
    permissions: "0600"
    content: |
      MONGO_URI=${mongo_uri}
      TIGER_URI=${tiger_uri}
%{ for key, value in app_env ~}
      ${key}=${value}
%{ endfor ~}
  - path: /opt/kip/Caddyfile
    content: |
      {$KIP_HOST} {
        reverse_proxy api:8080
      }
  - path: /opt/kip/compose.yaml
    content: |
      services:
        api:
          image: ${image}
          env_file: .env
          restart: unless-stopped
        worker:
          image: ${image}
          command: ["bun", "apps/server/src/main.worker.ts"]
          env_file: .env
          restart: unless-stopped
        caddy:
          image: caddy:2
          ports: ["80:80", "443:443"]
          environment:
            KIP_HOST: $${KIP_HOST}
          volumes:
            - ./Caddyfile:/etc/caddy/Caddyfile:ro
            - caddy_data:/data
          restart: unless-stopped
      volumes:
        caddy_data:

runcmd:
  - |
    IP=$(curl -sf http://169.254.169.254/v1/interfaces/0/ipv4/address || hostname -I | awk '{print $1}')
    echo "KIP_HOST=$(echo "$IP" | tr . -).sslip.io" >> /opt/kip/.env
  - echo '${registry_password}' | docker login ${registry_host} -u '${registry_user}' --password-stdin
  - cd /opt/kip && docker compose up -d
=== main.tf
resource "vultr_ssh_key" "team" {
  name    = "kip-team"
  ssh_key = REDACTED
}

resource "vultr_container_registry" "kip" {
  name   = "kip"
  region = var.region
  plan   = "start_up" # confirm plans in the provider docs
  public = false
}

resource "vultr_firewall_group" "api" {
  description = "kip-api"
}

resource "vultr_firewall_rule" "ssh" {
  firewall_group_id = vultr_firewall_group.api.id
  protocol          = "tcp"
  ip_type           = "v4"
  subnet            = var.admin_ip
  subnet_size       = 32
  port              = "22"
}

resource "vultr_firewall_rule" "web" {
  for_each          = toset(["80", "443"]) # 80 for Caddy's certificate challenge
  firewall_group_id = vultr_firewall_group.api.id
  protocol          = "tcp"
  ip_type           = "v4"
  subnet            = "0.0.0.0"
  subnet_size       = 0
  port              = each.value
}

# Survives `terraform apply -replace=vultr_instance.api`, so the sslip.io URL baked into the
# iOS build keeps working
resource "vultr_reserved_ip" "api" {
  label   = "kip-api"
  region  = var.region
  ip_type = "v4"
}

resource "vultr_instance" "api" {
  label             = "kip-api"
  region            = var.region
  plan              = "vc2-2c-4gb"
  os_id             = 2284 # Ubuntu 24.04
  ssh_key_ids       = [vultr_ssh_key.team.id]
  firewall_group_id = vultr_firewall_group.api.id
  reserved_ip_id    = vultr_reserved_ip.api.id

  # Installs Docker, writes .env and compose.yaml, derives an <ip>.sslip.io hostname for Caddy,
  # then pulls and runs the API, the worker and Caddy.
  user_data = templatefile("${path.module}/cloud-init.yaml.tftpl", {
    image             = var.image
    registry_host     = split("/", var.image)[0]
    registry_user     = var.registry_user
    registry_password = var.registry_password
    mongo_uri         = var.mongo_uri
    tiger_uri         = var.tiger_uri
    app_env           = var.app_env
  })
}

resource "mongodbatlas_project_ip_access_list" "api" {
  project_id = var.atlas_project_id
  ip_address = vultr_reserved_ip.api.subnet
  comment    = "kip-api"
}
=== variables.tf
variable "region" {
  description = "Vultr region; lhr is London. Confirm with `vultr-cli regions list`."
  type        = string
  default     = "lhr"
}

variable "admin_ip" {
  description = "Your public IPv4, the only address allowed to SSH in."
  type        = string
}

variable "ssh_public_key_path" {
  type    = string
  default = "~/.ssh/id_ed25519.pub"
}

variable "atlas_project_id" {
  type = string
}

variable "image" {
  description = "Full image reference in the Vultr registry, e.g. <registry host>/kip/kip:latest (Vultr console shows the host)."
  type        = string
}

variable "registry_user" {
  type      = string
  sensitive = true
}

variable "registry_password" {
  type      = string
  sensitive = true
}

variable "mongo_uri" {
  type      = string
  sensitive = true
}

variable "tiger_uri" {
  type      = string
  sensitive = true
}

variable "app_env" {
  description = "Other API secrets (GEMINI_API_KEY, ELEVENLABS_API_KEY, ...), written to the server's .env."
  type        = map(string)
  default     = {}
  sensitive   = true
}
=== outputs
output "api_ip" {
  value = vultr_reserved_ip.api.subnet
}

output "api_url" {
  value = "https://${replace(vultr_reserved_ip.api.subnet, ".", "-")}.sslip.io"
}

output "registry_urn" {
  description = "Registry address; push the image to <registry_urn>/kip:latest and set var.image to it."
  value       = vultr_container_registry.kip.urn
}
=== tfvars.example
# Copy to terraform.tfvars (git-ignored). Secrets can also come from TF_VAR_* env vars.
admin_ip          = "203.0.113.10"
atlas_project_id  = "..."
image             = "lhr.vultrcr.com/kip/kip:latest"
registry_user     = "..."
registry_password = "..."
mongo_uri         = "mongodb+srv://..."
tiger_uri         = "postgres://..."
app_env = {
  GEMINI_API_KEY     = "..."
  ELEVENLABS_API_KEY = "..."
}
check-cloud-init.sh

