import { createApp } from "./app";
import { ensureIndexes } from "./db/indexes";
import { migrate, readMigrations, type SqlClient } from "./db/migrate";
import { connectMongo, mongo } from "./db/mongo";
import { connectTiger, tiger } from "./db/tiger";
import { env } from "./env";

const { PORT, WEB_DIST, MONGO_URI, TIGER_URI } = env();

// Databases are optional: without them the API still serves /health, the web build and the stubs.
if (TIGER_URI) {
  await connectTiger();
  await migrate(tiger() as unknown as SqlClient, await readMigrations());
} else console.warn("TIGER_URI not set: skipping Tiger");
if (MONGO_URI) {
  await connectMongo();
  await ensureIndexes(mongo());
} else console.warn("MONGO_URI not set: skipping MongoDB");

const server = Bun.serve({ port: PORT, fetch: createApp({ webDist: WEB_DIST }).fetch });
console.log(`api listening on ${server.url}`);
=== env.ts
import { z } from "zod";

// Every variable from docs/ARCHITECTURE.md ("Env vars"), one line each, grouped by feature.
// All optional, so the API boots anywhere (it skips a database whose URI is missing, with a
// warning). Features check their own keys when they first use them, with a clear error.
const schema = z.object({
  // platform
  NODE_ENV: z.enum(["development", "test", "production"]).default("development"),
  PORT: z.coerce.number().default(3000),
  MONGO_URI: z.string().min(1).optional(),
  TIGER_URI: z.string().min(1).optional(),
  /** Directory of the Expo web export the API serves; unset in development */
  WEB_DIST: z.string().optional(),

  // labels, briefing (Gemini, paid tier)
  GEMINI_API_KEY: z.string().min(1).optional(),
  // labels, briefing (ElevenLabs)
  ELEVENLABS_API_KEY: z.string().min(1).optional(),
  // evidence (Solana mainnet, Memo program)
  SOLANA_RPC_URL: z.url().optional(),
  SOLANA_KEYPAIR: z.string().min(1).optional(),
  // works (Street Manager over SNS)
  STREET_MANAGER_TOPIC_ARN: z.string().min(1).optional(),
});

export type Env = z.infer<typeof schema>;

/** Parses an environment, treating blank values (`KEY=` in .env) as unset. */
export function parseEnv(source: Record<string, string | undefined>): Env {
  return schema.parse(Object.fromEntries(Object.entries(source).filter(([, v]) => v !== "")));
}

/**
 * The current environment. Parsing stays lazy, so importing this module never
 * requires a full environment. Each call reads `process.env` again: a feature
 * test can set its key just before using it, and a test file that parsed the
 * environment earlier cannot hide that key.
 */
export function env(): Env {
  return parseEnv(process.env);
}

/** A variable a feature can't run without. Throws a message that names it, never its value. */
export function requireEnv<K extends keyof Env>(key: K): NonNullable<Env[K]> {
  const value = env()[key];
  if (value === undefined || value === "")
    throw new Error(`${String(key)} is not set (see .env.example)`);
  return value as NonNullable<Env[K]>;
}
=== app.ts
import { trpcServer } from "@hono/trpc-server";
import { Hono } from "hono";
import { serveStatic } from "hono/bun";
import { cors } from "hono/cors";
import { labelsHttp } from "./features/labels";
import { worksHttp } from "./features/works";
import { createContext } from "./trpc/init";
import { appRouter } from "./trpc/router";

export function createApp({ webDist }: { webDist?: string } = {}): Hono {
  const app = new Hono();

  app.get("/health", (c) => c.json({ ok: true }));
  // The web build is same-origin in production; CORS covers the Expo dev server.
  app.use("/trpc/*", cors());
  app.use(
    "/trpc/*",
    trpcServer({
      router: appRouter,
      createContext: (_opts, c) => createContext({ req: c.req.raw }),
    }),
  );

  // Plain routes, one line per feature that has them. Written in M0.
  labelsHttp(app);
  worksHttp(app);

  if (webDist) {
    app.use("/*", serveStatic({ root: webDist }));
    // Single-page app: unknown paths get index.html so deep links work
    app.get("*", serveStatic({ root: webDist, path: "index.html" }));
  }
  return app;
}
=== main.worker.ts
import cron from "node-cron";
import { connectMongo } from "./db/mongo";
import { connectTiger } from "./db/tiger";
import { env } from "./env";
import { accountJobs } from "./features/account";
import { attributionJobs } from "./features/attribution";
import { briefingJobs } from "./features/briefing";
import { cityJobs } from "./features/city";
import { evidenceJobs } from "./features/evidence";
import { labelsJobs } from "./features/labels";
import { liveJobs } from "./features/live";
import { nightJobs } from "./features/night";
import { staysJobs } from "./features/stays";
import { worksJobs } from "./features/works";
import type { Job } from "./jobs";

// One entry per feature. Written in M0; feature work only edits its own `<feature>Jobs` list.
const jobs: Job[] = [
  ...cityJobs,
  ...nightJobs,
  ...attributionJobs,
  ...labelsJobs,
  ...briefingJobs,
  ...evidenceJobs,
  ...staysJobs,
  ...worksJobs,
  ...liveJobs,
  ...accountJobs,
];

const { MONGO_URI, TIGER_URI } = env();
if (TIGER_URI) await connectTiger();
if (MONGO_URI) await connectMongo();

for (const job of jobs) {
  cron.schedule(
    job.schedule,
    async () => {
      try {
        await job.run();
      } catch (error) {
        console.error(`job ${job.name} failed`, error);
      }
    },
    { name: job.name, noOverlap: true },
  );
}
console.log(`worker running ${jobs.length} jobs`);

