async () => {
  const accounts = await cloudflare.request({ method: "GET", path: "/accounts", query: { per_page: 50 } });
  const zones = await cloudflare.request({ method: "GET", path: "/zones", query: { name: "edenmatrix.xyz" } });
  const out = {
    accounts: accounts.result.map(a => ({ id: a.id, name: a.name })),
    zones: zones.result.map(z => ({ id: z.id, name: z.name, status: z.status, account: z.account?.id, plan: z.plan?.name })),
  };
  const acct = zones.result[0]?.account?.id ?? accounts.result[0]?.id;
  out.usingAccount = acct;
  const tunnels = await cloudflare.request({ method: "GET", path: `/accounts/${acct}/cfd_tunnel`, query: { is_deleted: false, per_page: 100 } });
  out.tunnels = [];
  for (const t of tunnels.result) {
    let ingress = null;
    if (t.remote_config) {
      try {
        const c = await cloudflare.request({ method: "GET", path: `/accounts/${acct}/cfd_tunnel/${t.id}/configurations` });
        ingress = (c.result?.config?.ingress ?? []).map(r => ({ hostname: r.hostname, service: r.service, path: r.path, originRequest: r.originRequest && Object.keys(r.originRequest).length ? r.originRequest : undefined }));
      } catch (e) { ingress = "error: " + e.message; }
    }
    out.tunnels.push({ id: t.id, name: t.name, status: t.status, remote_config: t.remote_config, config_src: t.config_src, created_at: t.created_at, connectors: (t.connections ?? []).length, ingress });
  }
  if (zones.result[0]) {
    const recs = await cloudflare.request({ method: "GET", path: `/zones/${zones.result[0].id}/dns_records`, query: { per_page: 200 } });
    out.dns = recs.result.map(r => ({ name: r.name, type: r.type, content: r.type === "TXT" ? "(txt)" : r.content, proxied: r.proxied, comment: r.comment ?? undefined }));
  }
  return out;
}

