  if (existing.result.length === 0) {
    dns = (await cloudflare.request({
      method: "POST",
      path: `/zones/${zoneId}/dns_records`,
      body: { type: "CNAME", name: hostname, content: target, proxied: true, ttl: 1, comment: "kip tunnel: Kip API and web dashboard (DurHack 2026), cloudflared on the VPS" },
    })).result;
  } else {
    const r = existing.result[0];
